// Created: 2026-10-18

/**
 * An image in a tool result is a base64 media block. Its payload is
 * one long high-entropy run, so the entropy layer covered it with bullets,
 * the API got invalid base64, and every Read of a PNG or JPEG came back as
 * "(media removed, rejected by API)" (card image-read-fault-2026-10-18).
 * The payload of a real media block passes through byte-equal; every text
 * field stays masked, and a `data` field outside a real media block too.
 */

import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, test } from "vitest";
import { register } from "../hooks/register.js";

type RegisteredHook = (...args: unknown[]) => unknown;

function toolCall(): RegisteredHook {
  const hooks = new Map<string, RegisteredHook>();
  register((event: string, hook: unknown) => {
    hooks.set(event, hook as RegisteredHook);
    return { catch: () => undefined };
  }, {});
  return hooks.get("tool.call")!;
}

const fake$ = {
  env: { get: async (): Promise<string | undefined> => undefined },
  ui: {
    notice: async (): Promise<void> => undefined,
    toast: async (): Promise<void> => undefined,
    status: async (): Promise<void> => undefined,
    log: async (): Promise<void> => undefined,
  },
  clock: { after: () => ({ cancel: () => undefined }) },
};

const next = (result: unknown) => async (): Promise<unknown> => result;

/** A high-entropy base64 run built at runtime, so no token sits in the source. */
const TOKEN = Buffer.from(Array.from({ length: 48 }, (_, i) => (i * 97 + 13) % 256)).toString("base64");

/** A valid 1x1 PNG, and a PDF with a token in its text (PDF stays masked). */
const PNG_1X1 =
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAIAAACQd1PeAAAADElEQVR4nGP4z8AAAAMBAQDJ/pLvAAAAAElFTkSuQmCC";
const PDF = Buffer.from("%PDF-1.4\n" + "x".repeat(40) + TOKEN).toString("base64");

/** A real image several kB long, read from disk. */
const here = dirname(fileURLToPath(import.meta.url));
const BIG_PNG = readFileSync(join(here, "fixtures", "media-block.png")).toString("base64");

async function run(result: unknown): Promise<string> {
  return JSON.stringify(await toolCall()(fake$, { tool: "Read", args: {} }, next({ result })));
}

describe("a base64 media block passes through byte-equal", () => {
  test.each([
    ["image/png", PNG_1X1],
    ["image/png", BIG_PNG],
  ])("%s payload is unchanged", async (mediaType, data) => {
    const out = await run([{ type: "image", source: { type: "base64", media_type: mediaType, data } }]);
    expect(out).toContain(data);
  });
});

/**
 * What tool.call really sees for a Read of an image on Claude Code 2.1.304:
 * the Read tool's own output, { type: "image", file: { base64, type, ... } },
 * not the API source block. With only the API shape exempt, a live Read of a
 * PNG still came back "invalid base64 data" (2026-10-20, paired probe).
 */
describe("the Read tool's image output passes through byte-equal", () => {
  test.each([
    ["image/png", PNG_1X1],
    ["image/png", BIG_PNG],
  ])("%s file.base64 is unchanged", async (mediaType, base64) => {
    const out = await run({
      type: "image",
      file: { base64, type: mediaType, originalSize: 70, dimensions: { originalWidth: 1, originalHeight: 1 } },
    });
    expect(out).toContain(base64);
  });

  test("a token in a Read-shaped file that claims image/png is masked", async () => {
    const out = await run({ type: "image", file: { base64: TOKEN, type: "image/png", originalSize: 48 } });
    expect(out).not.toContain(TOKEN);
  });

  test("a PDF in the Read shape stays masked", async () => {
    const out = await run({ type: "image", file: { base64: PDF, type: "application/pdf" } });
    expect(out).not.toContain(TOKEN);
  });
});

describe("every other string stays masked", () => {
  test("a token in a text block next to an image is masked", async () => {
    const out = await run([
      { type: "text", text: `key=${TOKEN}` },
      { type: "image", source: { type: "base64", media_type: "image/png", data: PNG_1X1 } },
    ]);
    expect(out).not.toContain(TOKEN);
    expect(out).toContain(PNG_1X1);
  });

  test("a token in a field named data outside a media block is masked", async () => {
    const out = await run({ data: TOKEN });
    expect(out).not.toContain(TOKEN);
  });

  test("a token dressed as a media block but not that media type is masked", async () => {
    const out = await run({ source: { type: "base64", media_type: "image/png", data: TOKEN } });
    expect(out).not.toContain(TOKEN);
  });

  test("a PDF payload stays masked: the API reads its text, the veil cannot", async () => {
    const out = await run([{ type: "document", source: { type: "base64", media_type: "application/pdf", data: PDF } }]);
    expect(out).not.toContain(PDF);
  });

  test("a token in a media block of a type the veil does not pass is masked", async () => {
    const out = await run({ source: { type: "base64", media_type: "text/plain", data: TOKEN } });
    expect(out).not.toContain(TOKEN);
  });
});
